<script setup lang="ts">
import {ref,computed,reactive,onMounted,onBeforeUnmount,watch} from 'vue';
import {Button,Input,Dialog,useHostContext} from '@openclaw-plugins/control-ui-kit';
import AuditView from './AuditView.vue';
import ScheduleEditor from './ScheduleEditor.vue';
import type {AuditPage} from './audit-model';
import {type ScheduleCatalog,type ManagedTask,type ManageAction,type ScheduleFields,type ScheduleConfirmation,type ScheduleDraft,labels,taskStatuses,deliveryLabels,scheduleText,scheduleDraft} from './schedule-model';
const props=defineProps<{invoke:<T>(action:string,payload:Record<string,unknown>)=>Promise<T>;canWrite:()=>boolean;safe:(v:unknown)=>string;groupName?:(task:ManagedTask)=>string;initialTaskId?:string|null;initialAction?:string|null;onChanged?:()=>unknown|Promise<unknown>;onClose?:()=>void;returnFocus?:()=>HTMLElement|null}>();
const context=useHostContext(),open=ref(true),data=ref<ScheduleCatalog>(),selected=ref(props.initialTaskId??''),creating=ref(false),loading=ref(false),busy=ref(false),error=ref(''),notice=ref(''),confirmation=ref<ScheduleConfirmation|null>(null),query=ref(''),auditOpen=ref(false);
const writable=computed(()=>!!context.value.host.connection.canWrite&&props.canWrite()),tasks=computed(()=>data.value?.tasks??[]),task=computed(()=>tasks.value.find(t=>t.id===selected.value));
const sources=computed(()=>tasks.value.filter(t=>t.kind!=='repository-sync'&&t.sourceValid&&!t.busy&&['enabled','paused','completed','removed'].includes(t.status)));
const source=computed(()=>creating.value?sources.value.find(t=>t.id===selected.value)??sources.value[0]:task.value);
const drafts=reactive(new Map<string,ScheduleDraft>()),draftKey=computed(()=>(creating.value?'create:':'edit:')+(source.value?.id??''));
const emptyDraft:ScheduleDraft={name:'',delivery:'source',kind:'cron',mode:'daily',expr:'0 9 * * *',tz:'Asia/Shanghai',at:'',daily:'09:00'};
const draft=computed(()=>{if(!source.value)return emptyDraft;if(!drafts.has(draftKey.value))drafts.set(draftKey.value,scheduleDraft(source.value,creating.value));return drafts.get(draftKey.value)!;});
const groupName=(t:ManagedTask)=>props.groupName?.(t)??'群名称未获取';
const matches=(t:ManagedTask)=>(t.name+' '+t.projectId+' '+groupName(t)+' '+(t.requester??'')+' '+(t.chatId??'')).toLocaleLowerCase().includes(query.value.toLocaleLowerCase());
let epoch=0,alive=true,initialAction=props.initialAction;
function close(){if(!open.value)return;open.value=false;epoch++;props.onClose?.();}
async function refresh(){const token=++epoch;loading.value=true;try{const next=await props.invoke<ScheduleCatalog>('scheduleCatalog',{});if(!alive||token!==epoch)return;data.value=next;if(!creating.value&&!next.tasks?.some(t=>t.id===selected.value))selected.value=next.tasks?.[0]?.id??'';if(initialAction){const action=initialAction as ManageAction;initialAction=null;const t=next.tasks?.find(t=>t.id===props.initialTaskId);if(t&&['pause','resume','remove'].includes(action)&&!actionDisabled(t,action))confirm(action,t);else error.value='任务状态或权限已变化，请核对当前计划后再操作。';}}catch(e){if(alive&&token===epoch)error.value=props.safe(e instanceof Error?e.message:e);}finally{if(alive&&token===epoch)loading.value=false;}}
function actionDisabled(t:ManagedTask,action:ManageAction){return busy.value||!writable.value||(t.status==='removed'&&!(t.kind==='repository-sync'&&action==='resume'))||(['run','resume'].includes(action)&&(!t.sourceValid||t.busy||!['enabled','paused',...(t.kind==='repository-sync'&&action==='resume'?['removed']:[])].includes(t.status)))||(action==='run'&&(!(t.canRun??data.value?.canRun)||t.status!=='enabled'))||(action==='pause'&&t.status!=='enabled')||(action==='resume'&&t.status==='enabled');}
function confirm(action:ManageAction,t:ManagedTask,fields:ScheduleFields={}){notice.value='';confirmation.value={action,...(action==='create'?{sourceId:t.id}:{id:t.id}),expectedRevision:t.revision,requestId:crypto.randomUUID(),confirmed:true,...fields};error.value='';}
function submit(fields:ScheduleFields){if(source.value)confirm(creating.value?'create':'update',source.value,fields);}
async function execute(){if(busy.value||!writable.value||!confirmation.value)return;const input={...confirmation.value},token=epoch;notice.value='';busy.value=true;try{const result=await props.invoke<{status:string;id?:string;skipped?:boolean}>('scheduleManage',input as unknown as Record<string,unknown>);if(!alive||token!==epoch)return;confirmation.value=null;notice.value=result.status==='succeeded'?(input.action==='run'?(result.skipped?'今日同步已由其他触发接纳，未重复入队。':'已提交 OpenClaw 原生队列；请在执行记录核验实际结果。'):input.action==='create'?'已创建，默认暂停。确认计划后启用。':'操作已完成。'):'操作结果待核验，请查看操作记录，不要重复提交。';if(result.status==='succeeded')drafts.delete(draftKey.value);selected.value=result.id??selected.value;creating.value=false;await props.onChanged?.();}catch(e){if(alive&&token===epoch){notice.value='';error.value=props.safe(e instanceof Error?e.message:e);confirmation.value=null;}}finally{if(alive&&token===epoch){busy.value=false;await refresh();}}}
const confirmTask=computed(()=>tasks.value.find(t=>t.id===(confirmation.value?.id??confirmation.value?.sourceId)));
const preview=computed(()=>{const c=confirmation.value,t=confirmTask.value;if(!c)return '';return c.at?`一次性 · ${c.at}`:scheduleText({...t?.schedule,...(c.expr?{kind:'cron',expr:c.expr}:{}),...(c.time?{time:c.time}:{}),...(c.timeZone?{tz:c.timeZone}:{})});});
const operations=computed(()=>(data.value?.operations??[]).filter(o=>task.value&&o.result?.id===task.value.id));
const auditInvoke=(action:string,payload:Record<string,unknown>)=>props.invoke<AuditPage>(action,payload);
watch(selected,()=>{auditOpen.value=false;});
onMounted(refresh);onBeforeUnmount(()=>{alive=false;epoch++;});
</script>
<template><Dialog :open="open" title="管理定时任务" :return-focus="returnFocus" content-class="ocp:max-w-6xl ar-schedule-manager" @update:open="close"><p class="ar-muted">统一管理群任务与仓库同步 · OpenClaw 原生调度</p><div class="ar-sync-dialog-body"><p v-if="error" role="alert" class="ar-error">{{error}}</p><p v-if="notice" role="status" class="ar-notice">{{notice}}</p><p v-if="loading">正在读取…</p><template v-if="!data?.available"><template v-if="!loading"><p>暂时无法读取定时任务，请刷新重试。</p><Button variant="outline" @click="error='';refresh()">重新读取</Button></template></template><template v-else><p v-if="!writable" class="ar-muted">当前连接只读；管理操作需要写入权限。</p><template v-if="confirmation"><h3>确认{{labels[confirmation.action]}}</h3><p>{{safe(confirmTask?.name+(confirmTask?.kind==='repository-sync'?' · 当前 Agent 全部登记项目':' · 原群 '+confirmTask?.chatId))}}</p><p class="ar-schedule-preview">{{safe(confirmation.name??confirmTask?.name)}}</p><p>{{safe(preview)}}</p><p v-if="confirmTask?.kind!=='repository-sync'">投递位置：{{deliveryLabels[confirmation.deliveryMode??confirmTask?.deliveryMode??'source']??'未知'}}</p><p>{{confirmation.action==='run'?(confirmTask?.kind==='repository-sync'?'通过 OpenClaw 执行今日同步；当天已尝试则跳过，不改变下一次计划。':'将立即在原群执行并回复；不会改变下一次计划时间。'):confirmation.action==='remove'?'计划移入回收站并停止后续触发，保留期内可恢复；已运行任务继续执行。':confirmation.action==='pause'?'阻止后续触发；已运行任务需另行核验。':'通过 OpenClaw 原生调度保存此计划。'}}</p><Button :variant="confirmation.action==='remove'?'destructive':'default'" :disabled="busy||!writable" @click="execute">{{busy?'正在提交…':'确认执行'}}</Button><Button variant="outline" :disabled="busy" @click="confirmation=null">取消</Button></template>
<div v-else class="ar-schedule-layout"><aside class="ar-schedule-sidebar"><div class="ar-schedule-actions"><Button :disabled="busy||!writable" @click="creating=true;selected='';notice=''">基于群请求新建</Button><Button variant="outline" :disabled="busy" @click="error='';refresh()">刷新</Button></div><Input v-model="query" type="search" aria-label="搜索任务" placeholder="搜索任务"/><p v-if="query&&!tasks.some(matches)" class="ar-muted">没有匹配的计划，试试其他关键词。</p><p class="ar-muted">{{tasks.length}} 个计划</p><div class="ar-schedule-choices"><Button v-for="t in tasks" :key="t.id" class="ocp:h-auto ocp:min-h-9 ocp:justify-start" variant="ghost" :aria-label="safe(t.name+' · '+(taskStatuses[t.status]??t.status))" :data-search="(t.name+' '+t.projectId+' '+groupName(t)+' '+(t.requester??'')+' '+(t.chatId??'')).toLowerCase()" :hidden="!matches(t)" :disabled="busy" :aria-current="selected===t.id&&!creating?'true':undefined" @click="selected=t.id;creating=false;notice=''"><strong>{{safe(t.name)}}</strong><span>{{t.kind==='repository-sync'?'系统同步':'群任务'}} · {{taskStatuses[t.status]??t.status}}</span><small>{{safe(scheduleText(t.schedule))}}</small></Button></div><p v-if="!tasks.length" class="ar-muted">还没有定时任务</p></aside><section class="ar-schedule-detail"><template v-if="task&&!creating"><h3>{{safe(task.name)}}</h3><p v-if="task.nativeWarning" class="ar-warning">{{safe(task.nativeWarning)}}</p><p v-if="task.busy" class="ar-warning">已有运行中、排队或结果待核验的记录，不能重复执行或编辑。</p><p v-if="!task.sourceValid" class="ar-warning">{{task.kind==='repository-sync'?'部署配置未授权仓库同步。只能暂停或删除。':'原群请求已失效。只能暂停或删除。'}}</p><p class="ar-schedule-preview">{{safe(scheduleText(task.schedule))}}</p><div class="ar-schedule-actions"><Button v-for="action in (['run',task.status==='enabled'?'pause':'resume','remove'] as ManageAction[])" :key="action" :variant="action==='remove'?'destructive':'outline'" :disabled="actionDisabled(task,action)" @click="confirm(action,task)">{{labels[action]}}</Button></div></template><h3 v-if="creating">基于已有群请求创建计划</h3><ScheduleEditor v-if="creating||task" :key="draftKey" :source="source" :sources="sources" :creating="creating" :draft="draft" :writable="writable" :busy="busy" :safe="safe" :group-name="groupName" @source="selected=$event" @submit="submit"/><p v-else class="ar-muted">选择一个计划查看设置，或基于已有群请求创建。</p><section class="ar-schedule-audit"><h3>最近管理操作</h3><p class="ar-muted">记录面板管理请求；提交成功不等于任务执行完成。</p><p v-if="!operations.length" class="ar-muted">当前任务暂无管理操作记录。</p><p v-for="(operation,index) in operations" :key="index">{{safe(new Date(operation.createdAt).toLocaleString()+' · '+(labels[operation.action as ManageAction]??operation.action)+' · '+({succeeded:'成功',unknown:'结果待核验',pending:'处理中或中断待核验'} as Record<string,string>)[operation.status])}}</p></section><details v-if="task&&!creating" @toggle="auditOpen=($event.target as HTMLDetailsElement).open"><summary>查看完整修改日志</summary><AuditView v-if="auditOpen" :invoke="auditInvoke" :safe="safe" feature="schedules" :target-id="task.id"/></details></section></div></template></div></Dialog></template>
